def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out"""
    # Simple approach: find first difference and see what we're replacing
    min_len = min(len(s_in), len(s_out))

    # Look for first position where characters differ
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # Strings are identical or one is prefix of other
        if len(s_in) == len(s_out):
            return None, None, -1
        else:
            # One string is longer - find which part was added/removed
            if len(s_in) < len(s_out):
                # Characters added at end
                return "", s_out[len(s_in):], len(s_in)
            else:
                # Characters removed at end
                return s_in[len(s_out):], "", len(s_out)

    # If we found a position where they differ
    # Check if it's a simple replacement of one character
    if len(s_in) == len(s_out):
        return s_in[pos], s_out[pos], pos
    else:
        # This is more complex - might be insertion/deletion
        # For now, let's focus on simple cases
        if len(s_in) > len(s_out):
            # Character deleted
            return s_in[pos], "", pos
        else:
            # Character inserted
            return "", s_out[pos], pos

